from base import *
body = cap("Today · the title is cut off") + compact(bars()+'<span>Everything Has Changed (feat. Ed S…</span>','<span class="ring" style="--p:55%"></span><span>4:21</span>')
body += cap("With a marquee · the title glides slowly past") + compact(bars()+'<span style="display:inline-block;overflow:hidden;max-width:120px"><span style="display:inline-block;white-space:nowrap">Everything Has Changed (feat. Ed Sheeran)&nbsp;&nbsp;&nbsp;</span></span>','<span class="ring" style="--p:55%"></span><span>4:21</span>')
inner = '<div style="display:flex;align-items:center;gap:14px"><div class="tile" style="width:44px;height:44px;display:flex;align-items:center;justify-content:center;font-size:18px">♫</div><div style="flex:1;min-width:0"><div style="font-size:15px;font-weight:600"><span style="display:inline-block;overflow:hidden;max-width:200px"><span style="display:inline-block;white-space:nowrap">Everything Has Changed (feat. Ed Sheeran)&nbsp;&nbsp;&nbsp;</span></span></div><div class="s" style="font-size:12px;margin-top:2px">Taylor Swift · Red (Taylor’s Version)</div><div class="bar" style="margin-top:8px"><i style="width:55%"></i></div></div></div>'
body += cap("Open notch · Now Playing") + opened(inner, h=110, tabs='<span class="on">♫</span><span>▤</span><span>⏱</span><span>▦</span>')
open("m16.html","w").write(page("Now Playing: scroll long titles instead of cutting them","A slow marquee on hover or always, so the full song name is readable in the ear and the widget.",body))
